public class ListNode
{
    public int Val;
    public ListNode? Next;
    public ListNode(int val, ListNode? next = null) { Val = val; Next = next; }
}
public static class ListBuilder
{
    public static ListNode? FromArray(int[] values)
    {
        ListNode? head = null, tail = null;
        foreach (var v in values)
        {
            var node = new ListNode(v);
            if (head == null) { head = node; tail = node; }
            else { tail!.Next = node; tail = node; }
        }
        return head;
    }
    public static int[] ToArray(ListNode? head)
    {
        var result = new List<int>();
        for (var current = head; current != null; current = current.Next)
        {
            if (result.Count == 10000) throw new InvalidOperationException("The returned list never reaches null (it loops back on itself).");
            result.Add(current.Val);
        }
        return result.ToArray();
    }
}
public static class MergeHarness
{
    public static int[] Run(int[] a, int[] b)
    {
        return ListBuilder.ToArray(Solution.MergeTwoLists(ListBuilder.FromArray(a), ListBuilder.FromArray(b)));
    }
}

